import json

def count_statuses(path):
    counts = {}
    with open(path, encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if line:
                try:
                    data = json.loads(line)
                    status = data.get('status')
                    if status:
                        counts[status] = counts.get(status, 0) + 1
                except json.JSONDecodeError:
                    continue
    return counts
